"""laoban API server (fixed template, not generated by AI).

Wraps the generated handler module:

    handler.handle(method: str, path: str, body: bytes) -> tuple[int, dict]

`path` is the request path without the query string, e.g. "/orders".
The returned dict (or list) is sent as JSON. Any exception becomes a
generic 500 response; the traceback goes to the container log only.
Requests are handled one at a time so the handler's module-level data
needs no locking. Python standard library only.

Environment:
  LAOBAN_CODE_DIR  directory holding handler.py (default /app)
  PORT             listen port (default 8080; 0 picks a free port)
"""

import http.server
import json
import os
import sys
import traceback
import urllib.parse

sys.dont_write_bytecode = True
sys.path.insert(0, os.environ.get("LAOBAN_CODE_DIR", "/app"))

import handler  # noqa: E402

PORT = int(os.environ.get("PORT", "8080"))
MAX_BODY = 1024 * 1024


class Handler(http.server.BaseHTTPRequestHandler):
    server_version = "laoban-api"
    sys_version = ""
    protocol_version = "HTTP/1.0"

    def _send(self, status, payload):
        body = json.dumps(payload, ensure_ascii=False).encode("utf-8")
        if status in (204, 304):
            body = b""
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.send_header("X-Content-Type-Options", "nosniff")
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(body)

    def _run(self):
        try:
            length = int(self.headers.get("Content-Length") or 0)
        except ValueError:
            self._send(400, {"error": "bad content-length"})
            return
        if length < 0 or length > MAX_BODY:
            self._send(413, {"error": "request body too large"})
            return
        body = self.rfile.read(length) if length else b""
        path = urllib.parse.urlsplit(self.path).path or "/"
        try:
            status, payload = handler.handle(self.command, path, body)
            status = int(status)
            if status < 200 or status > 599:
                raise ValueError("status out of range")
            json.dumps(payload)
        except Exception:
            traceback.print_exc(file=sys.stderr)
            self._send(500, {"error": "internal error"})
            return
        self._send(status, payload)

    do_GET = _run
    do_HEAD = _run
    do_POST = _run
    do_PUT = _run
    do_PATCH = _run
    do_DELETE = _run


def main():
    server = http.server.HTTPServer(("", PORT), Handler)
    print("laoban-api listening on port %d" % server.server_address[1], file=sys.stderr, flush=True)
    server.serve_forever()


if __name__ == "__main__":
    main()
